/// Builds level `index`'s moby class meshes and the images of the level start's entity groups.
pub fn prepare(level: &LoadedLevel, index: u32) -> MobyPrepared {
    let t0 = Instant::now();
    let m = &level.mobys;
    let lod_on = moby_lod::lod_enabled() && !m.cpu_light;
    // The classes a placed moby may become at run time (rc_game::moby_update::class_swap, G-CLS-031): only where the
    // moby loop runs the level's class code.
    let swaps = |o: i16| -> Vec<i16> {
        if !crate::gameplay::enabled() { return Vec::new(); }
        rc_game::moby_update::class_swap::targets(crate::gameplay::level_ports_for(index), o)
    };
    // Per placed instance, the other classes it may take at run time (`swaps`: a class swap of its class code): their
    // meshes, palette slots and metal entities are made with the level (MobyOcclusion::set_class).
    let class_ix: HashMap<i32, usize> = m.classes.iter().enumerate().map(|(i, c)| (c.o_class, i)).collect();
    let swap_to: Vec<Vec<usize>> = m.instances.iter().zip(&m.placed)
        .map(|(inst, p)| if p.is_none() { Vec::new() } else { swaps(inst.o_class as i16).into_iter().filter_map(|o| class_ix.get(&(o as i32)).copied()).collect() })
        .collect();
    // Class meshes, only for classes something instances (or may become), in class order (asset ids follow it).
    let used: BTreeSet<usize> = m.placed.iter().flatten().map(|p| p.class).chain(swap_to.iter().flatten().copied()).collect();
    let classes: Vec<_> = used
        .iter()
        .map(|&ci| {
            let c = &m.classes[ci];
            let high = build_part_meshes(c, &c.class.high_lod, false, glow_from(c, false));
            let low = if lod_on && !c.class.low_lod.is_empty() { build_part_meshes(c, &c.class.low_lod, c.class.header.low_lod_joint_count == 0, glow_from(c, true)).0 } else { Vec::new() };
            (ci, high, low, build_metal_part_meshes(c))
        })
        .collect();
    // The images in the order `spawn_mobys`'s eager groups first ask for them (asset ids follow it): per instance, its
    // high then low parts' textures, then the metal maps of its class and of the classes it may become.
    let by_class: HashMap<usize, usize> = classes.iter().enumerate().map(|(k, c)| (c.0, k)).collect();
    let (mut seen, mut seen_metal) = (HashSet::new(), HashSet::new());
    let mut images = Vec::new();
    for (ii, p) in m.placed.iter().enumerate() {
        let Some(p) = p else { continue };
        let (_, (high, _), low, _) = &classes[by_class[&p.class]];
        let lists: &[&Vec<PartMesh>] = if lod_on { &[high, low] } else { &[high] };
        for part in lists.iter().copied().flatten() {
