                if seen_metal.insert(part.kind) {
                    let (img, range) = metal_image_data(level, part.kind);
                    images.push((PreparedImage::Metal(part.kind), img, range));
                }
            }
        }
    }
    MobyPrepared { swap_to, classes, images, build: t0.elapsed() }
}

