/// Adds a [`prepare`]d level's shrub meshes, images (both through `stream`: a few per frame while a flight streams
/// the level, crate::level_stream), buffers and materials and spawns the part entities (hidden until `cull_system`
/// shows them): with the level start's commands, or over the next frames while streaming. Returns the wind sway state.
#[allow(clippy::too_many_arguments)]
fn spawn_prepared(
    commands: &mut Commands,
    p: ShrubPrepared,
    stream: &mut crate::level_stream::LevelStream,
    meshes: &mut Assets<Mesh>,
    images: &mut Assets<Image>,
    materials: &mut Assets<ShrubMaterial>,
    buffers: &mut Assets<ShaderBuffer>,
    layer: Option<&bevy::camera::visibility::RenderLayers>,
) -> (Stats, ShrubSway) {
    let t0 = Instant::now();
    let mesh_handles: Vec<Handle<Mesh>> = p.meshes.into_iter().map(|m| stream.mesh(meshes, m)).collect();
    let inst_buffer = buffers.add(ShaderBuffer::new(&p.records, RenderAssetUsages::RENDER_WORLD));
    // No point light on any instance until crate::world_lights writes one.
    let data = ShrubSway::initial_data(p.sway_len);
    let sway_buffer = buffers.add(ShaderBuffer::new(&data, RenderAssetUsages::default()));
    let sway = ShrubSway { enabled: sway_enabled(), buffer: sway_buffer.clone(), len: p.sway_len, instances: p.sway_instances, last_tick: None, data };
    let image_handles: Vec<Handle<Image>> = p.images.into_iter().map(|i| stream.image(images, i)).collect();
    let material_handles = p
        .materials
        .iter()
        .map(|&(image, list, mxl, pass)| {
            materials.add(ShrubMaterial {
                texture: image_handles[image].clone(),
                fog: crate::game_camera::fog_buffer(),
                params: ShrubParams { misc: Vec4::new(list as f32, mxl as f32, crate::game_camera::NEAR, 0.0) },
                instances: inst_buffer.clone(),
                sway: sway_buffer.clone(),
                pass,
            })
        })
        .collect();
    let mut spawn = ShrubSpawn { meshes: mesh_handles, materials: material_handles, plan: p.plan, layer: layer.cloned(), next: 0 };
    if stream.deferring() {
        stream.job(Box::new(move |world, deadline| spawn.run(world, Some(deadline))));
    } else {
        commands.queue(move |world: &mut World| { spawn.run(world, None); });
    }
    let mut st = p.stats;
    st.spawn = t0.elapsed();
    (st, sway)
}

/// The part entities of a [`ShrubPrepared`], spawned in order.
struct ShrubSpawn {
    meshes: Vec<Handle<Mesh>>,
    materials: Vec<Handle<ShrubMaterial>>,
    plan: Vec<PartEntity>,
    layer: Option<bevy::camera::visibility::RenderLayers>,
    /// The next entity to spawn.
    next: usize,
}

impl ShrubSpawn {
    /// Spawns the next part entities until `deadline` (None: all); true when nothing is left.
    fn run(&mut self, world: &mut World, deadline: Option<Instant>) -> bool {
        while self.next < self.plan.len() {
            let pe = &mut self.plan[self.next];
            let mut e = world.spawn((
                Mesh3d(self.meshes[pe.mesh].clone()),
                MeshMaterial3d(self.materials[pe.material].clone()),
                pe.transform,
                MeshTag(pe.tag),
                pe.cull,
                WorldDrawOrder(pe.order),
                Visibility::Hidden,
                Name::new(std::mem::take(&mut pe.name)),
            ));
            if pe.no_frustum { e.insert(NoFrustumCulling); }
            if let Some(l) = &self.layer { e.insert(l.clone()); }
            self.next += 1;
            if self.next.is_multiple_of(64) && deadline.is_some_and(|d| Instant::now() >= d) { break; }
        }
        self.next >= self.plan.len()
    }
}

