/// A tracking-space gesture, converted to game coordinates by the VR adapter.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TrackedPunch {
    pub direction: [f32;3],
    pub begin: bool,
}

/// Physical punches enter the original lunge, retaining its windup, horizontal speed,
/// attack window, broad collision volumes, sounds and effects.
pub(super) fn tracked_fire(h: &mut Hero,c: &mut Ctx) -> bool {
    // The punch stays offered until a lunge takes it (the VR adapter expires it): a punch thrown during a lunge
    // chains once its hit window is over.
    let Some(punch) = h.walloper.tracked_punch.filter(|p|p.begin) else {return false};
    let chain = h.state == LUNGE && h.timer > ticks(22);
    if !h.items.tracked || h.items.slot.id != WALLOPER || h.items.slot.state != 2
        || h.items.slot.item.is_none() || h.state == 1
        || (!chain && h.group > 1 && !(h.group == 4 && h.jump.landed != 0)) { return false; }
    h.walloper.tracked_punch = None;
    let d = punch.direction;
    let toward = (d[0].hypot(d[1]) > 0.2).then(|| d[1].atan2(d[0])).or_else(|| tracked_aim_yaw(h));
    h.walloper.tracked_yaw = Some(tracked_lunge_yaw(h, toward));
    h.set_state(c,LUNGE,true);
    h.fx.item_sounds.push(SWING_SOUND);
    true
}

/// VR: how far the lunge turns from the player's facing toward the punch or the aim (25°).
const TRACKED_TURN: f32 = 0.436;

/// VR: the lunge goes where the player faces (the heading the stick follows: the body or the gaze), turned at most
/// [`TRACKED_TURN`] toward `toward` (the punch or the controller's aim): an arm folding back, a controller pointing
/// behind or the stick pulled back never sends Ratchet backward.
fn tracked_lunge_yaw(h: &Hero, toward: Option<f32>) -> f32 {
    let heading = h.tracked.navigation.map(|v| to_f32x3(v.rows[0])).filter(|f| f[0].hypot(f[1]) > 0.1)
        .map_or(h.rot[2].to_f32(), |f| f[1].atan2(f[0]));
    toward.map_or(heading, |t| {
        let turn = crate::moby_update::creature::sub_rot(t, heading).clamp(-TRACKED_TURN, TRACKED_TURN);
        crate::moby_update::creature::add_rot(heading, turn)
    })
}

/// VR: the Walloper controller's horizontal aim (none when it points up or down).
fn tracked_aim_yaw(h: &Hero) -> Option<f32> {
    h.items.tracked_aim.map(|a| a.forward).filter(|f| f[0].hypot(f[1]) > 0.2).map(|f| f[1].atan2(f[0]))
}

