fn off_hand_ring(rt: &mut MenuRt, ring: &mut OffHandRing, gate: &HeroGate, g: &mut rc_game::game_state::Global, sess: &rc_game::game_state::SessionState, vsync: u32, tick: u64, listeners: i32) {
    let tri = rc_game::pad::button::TRIANGLE;
    let Some(qs) = rt.qs_left.as_mut().filter(|_| ring.akimbo) else {
        ring.was_held = false;
        return;
    };
    let (held, pressed) = (ring.held, ring.held && !ring.was_held);
    ring.was_held = held;
    let axis = |v: f32| rc_game::ps2v::Pf::f(v.clamp(-1.0, 1.0));
    let bits = |on: bool| if on { tri } else { 0 };
    let inp = MenuInput {
        held: bits(held),
        pressed: bits(pressed),
        held_u: bits(held),
        pressed_u: bits(pressed),
        // Screen y grows downward, the ring's stick like the pad's.
        stick_x: axis(ring.direction.x),
        stick_y: axis(-ring.direction.y),
        stick_active: ring.direction != Vec2::ZERO,
        connected: true,
        ..Default::default()
    };
    // The session's hand request and the double tap belong to the hand: the ring works on a copy.
    let mut s = *sess;
    let opened = qs.hero(&inp, gate, g, &mut s).opened;
    // Its page (a new one re-arms the pick, as the hand's ring's paging does).
    if opened || qs.entries.iter().zip(&ring.items).any(|(e, &item)| e.item != item) {
        for (k, &item) in ring.items.iter().enumerate() { qs.set_entry(k, item); }
        qs.greyed = ring.greyed;
        if !opened {
            qs.sel = -1;
            qs.arm = 1;
        }
    }
    // The ring repeats its pick on every frame of its fade-out: the one of the close only.
    let ev = qs.update(&inp, gate, g, &mut s, vsync, listeners);
    if ev.closed && ev.drone {
        ring.drone = true;
    } else if ev.closed {
        ring.picked = ev.request;
    }
    qs.draw(&rt.assets, g, tick, listeners, &mut rt.draws);
}

