    pub(crate) fn tracked_item_shape(&self, hand: &rc_game::hero::items::HandItem) -> Vec<(Vec3,f32)> {
        let Some(item) = self.items.iter().find(|i| i.o_class==hand.o_class && i.attach.slot==Slot::Hand) else {return Vec::new()};
        let palette = moby_anim::evaluate_with_snapshot(&item.anim,&hand.anim,hand.snapshot.as_ref());
        Self::contact_shape(item,hand.rows,hand.position,hand.scale,&palette)
