    pub(crate) fn tracked_body_hands(&mut self, poses: [Option<Transform>; 2], body: u8, grips: [f32; 2], hero: &rc_game::hero::Hero) {
        for item in self.items.iter_mut() {
            let Some((owner, side, _, _, _)) = BODY_HANDS.into_iter().find(|h| h.4 == item.o_class) else { continue };
            item.visible = false;
            item.tracked_palette = None;
            let owner_body = match owner { 87 => 1, 419 => 2, _ => 3 };
            let Some(pose) = poses[side].filter(|_| body == owner_body) else { continue };
            if owner == 87 && rc_game::hero::tracked::ledge_hold(hero.state) && hero.tracked.grabbed[side] {
                // Clank's hang (sequence 10): his palms hook the lip; they move under 5 mm across its frames.
                let mut hang = AnimState::spawn(&item.anim);
                if item.anim.frame(10, 0).is_some() {
                    (hang.seq_a, hang.seq_b, hang.frame_a, hang.frame_b, hang.t) = (10, 10, 0, 0, 0.0);
                }
                let Some(palm) = moby_anim::evaluate_chains(&item.anim, &hang, None, &[item.lists[0].as_slice()]).into_iter().next() else { continue };
                let r = hero.moby_rows;
                let axes = Mat3::from_cols_array(&[
                    r[0][0].to_f32(), r[0][1].to_f32(), r[0][2].to_f32(),
                    r[1][0].to_f32(), r[1][1].to_f32(), r[1][2].to_f32(),
                    r[2][0].to_f32(), r[2][1].to_f32(), r[2][2].to_f32()]);
                let palm_local = Vec3::new(palm[3][0], palm[3][1], palm[3][2]) * (item.scale / 1024.0);
                let centre = Vec3::from_array(hero.tracked_ledge_anchor());
                let anchor = Vec3::from_array(hero.tracked.anchors[side].unwrap_or(hero.tracked_ledge_anchor()));
                let tangent = Vec3::new(-hero.ledge_blk.yaw.sin(), hero.ledge_blk.yaw.cos(), 0.0);
                // As Ratchet's ledge hands: the native hang offset across the edge, the controller's anchor along it.
                let native_offset = Vec3::from_array(hero.position()) + axes * palm_local - centre;
                let contact = anchor + native_offset - tangent * native_offset.dot(tangent);
                item.position = (contact - axes * palm_local).to_array();
                item.rows = [0, 1, 2].map(|i| { let c = axes.col(i); [c.x.to_bits(), c.y.to_bits(), c.z.to_bits(), 0] });
                item.tracked_palette = Some(moby_anim::evaluate(&item.anim, &hang));
                item.visible = true;
                continue;
            }
            let rest = AnimState::spawn(&item.anim);
            let Some(palm) = moby_anim::evaluate_chains(&item.anim, &rest, None, &[item.lists[0].as_slice()]).into_iter().next() else { continue };
            let palm = Mat4::from_cols_array_2d(&palm);
            let basis = Mat3::from_mat4(palm);
            if !basis.determinant().is_finite() || basis.determinant().abs() < 1e-5 { continue; }
            let r = crate::game_camera::game_rows(&pose);
            let desired = if side == 0 { Mat3::from_cols(r[2], r[0], r[1]) } else { Mat3::from_cols(r[2], -r[0], -r[1]) };
            let axes = desired * basis.inverse();
            let anchor = palm.w_axis.truncate() * (item.scale / 1024.0);
            item.position = (crate::game_camera::game_eye(&pose) - axes * anchor).to_array();
            item.rows = [0, 1, 2].map(|i| { let c = axes.col(i); [c.x.to_bits(), c.y.to_bits(), c.z.to_bits(), 0] });
            // Clank's and the disguise's fingers close with the grip; Giant Clank's hands keep the rest pose.
            let fist = match owner {
                87 => fist_mods(&CLANK_FIST[side], side, fist_amount(grips[side])),
                DISGUISE_CLASS => fist_mods(&DISGUISE_FIST[side], side, fist_amount(grips[side])),
                _ => Vec::new(),
            };
            item.tracked_palette = Some(moby_anim::evaluate_posed(&item.anim, &rest, None, &[], &fist));
            item.visible = true;
        }
        self.ticks = self.ticks.wrapping_add(1);
    }
