    #[cfg(feature = "vr")]
    pub(crate) fn tracked_grips(&self, play: &crate::gameplay::Play) -> Option<[Vec3; 2]> {
        let palms = self.hand_frames(play, false)?;
        let w = self.weapon_attachment(play)?.inverse();
        let scale = self.items.iter().find(|i| i.o_class == -30001)?.scale / 1024.0;
        let mut grips = palms.map(|p| w.transform_point3(Vec3::from_array(p[3][..3].try_into().unwrap()) * scale));
        if Self::gold_devastator(play) {
