    /// Free palms follow controllers; held palms retain the exact native fingers, wrist and cuff pose relative to the weapon.
    #[cfg(feature = "vr")]
    /// `grips`: the left / right grip values; a free hand closes into a fist with its grip.
    pub(crate) fn tracked_hands(&mut self, poses: [Option<Transform>; 2], play: &crate::gameplay::Play, weapon: Option<&rc_game::hero::items::HandItem>, support: bool, grips: [f32; 2]) {
        let palette = self.hand_palette(play, false, &[]);
        let fists: [Option<Vec<Rows>>; 2] = std::array::from_fn(|side| {
            let amount = fist_amount(grips[side]);
            (amount > 0.0).then(|| self.hand_palette(play, false, &fist_mods(&RATCHET_FIST[side], side, amount))).flatten()
        });
        let palms = self.hand_frames(play, false);
        let hanging = matches!(play.game.hero.state,0x18..=0x1b);
        let ledge_palette = hanging.then(||self.hand_palette(play,true,&[])).flatten();
        let ledge_palms = hanging.then(||self.hand_frames(play,true)).flatten();
        let attachment = self.weapon_attachment(play);
        let support_anchor = Self::gold_devastator(play).then(|| self.tracked_grips(play)).flatten().map(|g|g[1]);
        for (side, pose) in poses.into_iter().enumerate() {
            let Some(item) = self.items.iter_mut().find(|i| i.o_class == -30000 - side as i16) else { continue };
            item.visible = false;
            item.tracked_palette = None;
            let Some(pose) = pose else { continue };
            let ledge_hand = hanging && play.game.hero.tracked.grabbed[side];
            let Some(f) = (if ledge_hand { ledge_palette.as_ref() } else { palette.as_ref() }) else { continue };
            let Some(palms) = (if ledge_hand { ledge_palms } else { palms }) else {continue};
            let palm = Mat4::from_cols_array_2d(&palms[1-side]);
            let held = weapon.filter(|_| side == 1 || support).zip(attachment);
            let (axes, mut position) = if ledge_hand {
                let hero = &play.game.hero;
                let r = hero.moby_rows;
                let axes = Mat3::from_cols_array(&[
                    r[0][0].to_f32(),r[0][1].to_f32(),r[0][2].to_f32(),
                    r[1][0].to_f32(),r[1][1].to_f32(),r[1][2].to_f32(),
                    r[2][0].to_f32(),r[2][1].to_f32(),r[2][2].to_f32()]);
                let centre = Vec3::from_array(hero.tracked_ledge_anchor());
                let anchor = Vec3::from_array(hero.tracked.anchors[side].unwrap_or(hero.tracked_ledge_anchor()));
                let palm_local = palm.w_axis.truncate()*(item.scale/1024.0);
                let tangent = Vec3::new(-hero.ledge_blk.yaw.sin(),hero.ledge_blk.yaw.cos(),0.0);
                // Preserve the original wrist depth/height and hooked fingers relative to the lip.
                // Only move it along the edge to this controller's accepted anchor.
                let native_offset = Vec3::from_array(hero.position())+axes*palm_local-centre;
                let contact = anchor+native_offset-tangent*native_offset.dot(tangent);
                (axes,contact-axes*palm_local)
            } else if let Some((weapon, attachment)) = held {
                let rows = weapon.rows.map(|r| Vec3::new(f32::from_bits(r[0]),f32::from_bits(r[1]),f32::from_bits(r[2])));
                let axes = Mat3::from_cols(rows[0], rows[1], rows[2]) * Mat3::from_mat4(attachment).inverse();
                let position = Vec3::from_array(weapon.position) - axes * attachment.w_axis.truncate();
                if weapon.o_class == rc_game::hero::melee::WRENCH_CLASS && play.game.hero.tracked.crank_target.is_some() {
                    // Shaft extension must not stretch Ratchet's fingers or glove.
                    let local = palm.w_axis.truncate() * (item.scale / 1024.0);
                    let contact = position + axes * local;
                    let x = rows[0].normalize_or_zero();
                    let z = x.cross(rows[1]).normalize_or_zero();
                    let y = z.cross(x).normalize_or_zero();
                    let rigid = Mat3::from_cols(x, y, z) * Mat3::from_mat4(attachment).inverse();
                    (rigid, contact - rigid * local)
                } else { (axes, position) }
            } else {
                let basis = Mat3::from_mat4(palm);
                if !basis.determinant().is_finite() || basis.determinant().abs() < 1e-5 { continue; }
                let r = crate::game_camera::game_rows(&pose);
                let desired = if side == 0 { Mat3::from_cols(r[2], r[0], r[1]) } else { Mat3::from_cols(r[2], -r[0], -r[1]) };
                let axes = desired * basis.inverse();
                let anchor = palm.w_axis.truncate() * (item.scale / 1024.0);
                (axes, crate::game_camera::game_eye(&pose) - axes * anchor)
            };
            if side==0 && support && !ledge_hand {
                if let Some((weapon,anchor)) = weapon.zip(support_anchor) {
                    let rows = weapon.rows.map(|r| Vec3::new(f32::from_bits(r[0]),f32::from_bits(r[1]),f32::from_bits(r[2])));
                    let target = Vec3::from_array(weapon.position)+Mat3::from_cols(rows[0],rows[1],rows[2])*anchor;
                    let palm_at = position+axes*(palm.w_axis.truncate()*(item.scale/1024.0));
                    position += target-palm_at;
                }
            }
            item.position = position.to_array();
            item.rows = [0,1,2].map(|i| { let r = axes.col(i); [r.x.to_bits(),r.y.to_bits(),r.z.to_bits(),0] });
            // A free hand (nothing held, not on a ledge) closes with its grip.
            let free = !ledge_hand && held.is_none() && !(side == 0 && support);
            item.tracked_palette = Some(fists[side].as_ref().filter(|_| free).unwrap_or(f).clone());
            item.visible = true;
        }
        self.ticks = self.ticks.wrapping_add(1);
    }
