/// How closed a hand is for a grip value: open below 0.1, a full fist from 0.9.
#[cfg(feature = "vr")]
fn fist_amount(grip: f32) -> f32 { ((grip - 0.1) / 0.8).clamp(0.0, 1.0) }
#[cfg(feature = "vr")]
fn fist_mods(hand: &Fingers, side: usize, amount: f32) -> Vec<moby_anim::JointModifier> {
    let sign = if side == 1 { -1.0 } else { 1.0 };
    let turn = |axis: Vec3, angle: f32| Quat::from_axis_angle(axis, angle).to_array();
    let curl = |joints: &'static [u8], axis: Vec3, angle: f32| {
        joints.iter().map(move |&j| moby_anim::JointModifier { quat: turn(axis, angle), ..moby_anim::JointModifier::compose(j) })
    };
    if amount <= 0.0 { return Vec::new(); }
    curl(hand.fingers, Vec3::X, sign * hand.curl * amount).chain(curl(hand.thumb, Vec3::Z, -sign * hand.thumb_curl * amount)).collect()
}

