/// The left hand's item (akimbo, `rc_game::hero::off_hand`) as the presentation placed it; None hides it. After
/// [`Self::tracked_items`], which hides every item it is not given.
#[cfg(feature = "vr")]
pub(crate) fn tracked_off_hand(&mut self, held: Option<&rc_game::hero::items::HandItem>, mods: &[moby_anim::JointModifier]) {
    for item in self.items.iter_mut().filter(|i| i.attach.slot == Slot::OffHand) {
        item.visible = false;
        let Some(h) = held.filter(|h| h.o_class == item.o_class) else { continue };
        item.visible = true;
        (item.position, item.scale, item.rows, item.state) = (h.position, h.scale, h.rows, h.anim);
        item.snapshot = h.snapshot.clone();
        item.mods = mods.to_vec();
    }
    self.ticks = self.ticks.wrapping_add(1);
}

