/// External tracked-body translation through the same capsule resolver, without advancing gameplay,
/// applying platform carry twice or replacing the hero's stick/jump velocity.
pub fn roomscale_move(&mut self, env: &Env, delta: [f32; 3]) {
    // A carrier (Rilgar's hover car, Kerwan's transports, the ferries, path platforms) sets the edge brake and the
    // jump lockout every tick of the ride: its walls only exist inside the tick, so a step here would leave it.
    if !matches!(self.mode, 0..=3) || self.health <= 0 || self.frozen != 0
        || self.no_vel_clamp != 0 || self.wall_spline != 0 || self.edge_brake != 0 || self.jump_lockout != 0
        || matches!(self.group, 3 | 0xf | 0x11 | 0x12 | 0x15 | 0x16) { return; }
    let length = delta.iter().map(|v|v*v).sum::<f32>().sqrt();
    if !length.is_finite() || length < 0.00001 { return; }
    let steps = (length / (self.cap_radius.to_f32().max(0.1) * 0.25)).ceil().clamp(1.0, 32.0) as usize;
    let step = delta.map(|v| v / steps as f32);
    for _ in 0..steps {
        let before = self.pos;
        self.pos[0] = self.pos[0] + Pf::f(step[0]);
        self.pos[1] = self.pos[1] + Pf::f(step[1]);
        self.pos[2] = self.pos[2] + Pf::f(step[2]);
        if !self.capsule_try(env) { self.pos = before; break; }
        self.tracked_floor_sweep(env, before);
    }
    // Record the latest safe position without destroying the previous simulation rollback point.
    self.pos_hist[self.pos_hist_idx as usize] = self.pos;
}

