/// `SetPlanarVel` in gravity modes ≠ 0 (`0x232738`): vel = the moby's facing row × speed.
pub(super) fn frame_planar_vel(h: &mut Hero) {
    if h.tracked_free_facing() {
        let up = rows_of(h.rot)[2];
        let direction = f3(h.stick_world);
        let direction = sub(direction, scl(up, dot(direction, up)));
