/// Physical headset view for VR, with the post-move body translation applied to the sampled eye.
/// The authored camera remains available to scripts and the ordinary desktop path.
pub fn listener_for_hero(cam: &CameraView, hero: &Hero) -> Listener {
    let Some(view) = hero.tracked.view.as_ref() else { return listener_of(cam) };
    let mut listener = listener_of(view);
    let pos = hero.position();
    for k in 0..3 { listener.pos[k] += pos[k] - hero.tracked.view_origin[k]; }
    listener
}

