            .and_then(|a| opts.items.iter().position(|it| it.action == 3 && it.arg == a))
            .map(|i| i + 1)
            .or_else(|| opts.items.iter().position(|it| it.action == 3 && it.arg == ad.port_quit))
            .unwrap_or(n);
        // The title: the model's title label (flags 0xf, large, centred) with the page's title.
        let Some(mut title) = self.widgets.get(&model.widgets[0]).cloned() else { return false };
        let Data::Label(l) = &mut title.data else { return false };
        l.id = spec.title as u32;
        title.addr = spec.title_w;
        let settings = Widget {
            addr: spec.list_w,
            update: UPDATE,
            draw: DRAW,
            enter: 0,
            leave: 0,
            dflags: 0,
            moby: 0,
            rect: [0; 4],
            raw: [0; 8],
            data: Data::Port(PortList { cursor: 0, top: 0, values: vec![0; spec.rows.len()], choices: vec![u32::MAX; spec.rows.len()] }),
        };
        let page = self.port_page(spec.page, &model, ad.port_options, spec.title_w, spec.list_w);
        // The Options description label: the disc table (one id per item, variant 0; the one already patched by an
        // earlier port page) with ours inserted.
        if let Some(Data::Label(l)) = self.widgets.get_mut(&ad.port_options_label).map(|w| &mut w.data) {
            let mut t: Vec<u32> = l.table.clone().unwrap_or_else(|| {
                (0..n as u32).map(|k| ov.u32(l.id.wrapping_add(k.wrapping_mul(l.stride) & !3)).unwrap_or(0)).collect()
            });
            t.insert(at.min(t.len()), spec.description as u32);
            l.table = Some(t);
        }
        if let Some(Data::List(opts)) = self.widgets.get_mut(&ad.port_options_list).map(|w| &mut w.data) {
            opts.items.insert(at, Item { label: spec.entry as i16, action: 3, arg: spec.page, sublabel: 0, hl: 0 });
        }
        self.widgets.insert(spec.title_w, title);
        self.widgets.insert(spec.list_w, settings);
        self.pages.insert(spec.page, page);
        self.install_front_port_page(ad.port_front_options, spec);
        true
    }

    /// A port page modelled on `model`: its frames and fillers, the model's title label replaced by `title_w` and its
    /// list (widget 3) by `list_w`.
    fn port_page(&self, addr: u32, model: &Page, parent: u32, title_w: u32, list_w: u32) -> Page {
        let mut widgets = model.widgets;
        if let Some(t) = widgets.iter_mut().find(|w| matches!(self.widgets.get(w).map(|x| &x.data), Some(Data::Label(_)))) { *t = title_w; }
        widgets[3] = list_w;
        Page { addr, seqs: model.seqs, parent, kind: KIND, focus: list_w, widgets, pending: 0 }
    }

    /// The main menu's copy of a port page and its entry in the front end's Options lists (nothing when the front
    /// end's pages are missing).
    fn install_front_port_page(&mut self, front_options: u32, spec: &ListPage) {
        if !self.pages.contains_key(&front_options) { return; }
        let sound = self.saves.front_options.iter().flatten().find(|it| it.action == 3 && it.label == FRONT_SOUND_LABEL).map(|it| it.arg);
        let Some(model) = sound.and_then(|a| self.pages.get(&a)).cloned() else { return };
        let page = self.port_page(spec.front, &model, front_options, spec.title_w, spec.list_w);
        self.pages.insert(spec.front, page);
        for list in self.saves.front_options.iter_mut() {
            if !list.iter().any(|it| it.arg == spec.front) {
                list.push(Item { label: spec.entry as i16, action: 3, arg: spec.front, sublabel: 0, hl: 0 });
            }
        }
    }

    /// The value index of a port setting (None without its page).
    pub fn port_value(&self, s: Setting) -> Option<u8> {
        let (w, _, r) = locate(s)?;
        list(self, w)?.values.get(r).copied()
    }

    /// Sets a port setting's value index (from the engine's current value), clamped to the row's values.
    pub fn set_port_value(&mut self, s: Setting, v: u8) {
        let Some((w, rows, r)) = locate(s) else { return };
        let max = rows[r].values.len().saturating_sub(1) as u8;
        if let Some(slot) = list_mut(self, w).and_then(|p| p.values.get_mut(r)) { *slot = v.min(max); }
    }

    /// Restricts a port setting to some of its values (bit k = value index k; ✕ skips the others). Value 0 stays
    /// selectable whatever the mask, so a row always has a choice.
    pub fn set_port_choices(&mut self, s: Setting, mask: u32) {
        let Some((w, rows, r)) = locate(s) else { return };
        if let Some(p) = list_mut(self, w) {
            if p.choices.len() < rows.len() { p.choices.resize(rows.len(), u32::MAX); }
            p.choices[r] = mask | 1;
        }
    }
}

