/// VR: the take-off's ride (crate::vr::body::ride): none until the ship has moved 0.3 from where the take-off began;
/// then each actor's correction keeping the place it had in the ship's frame (`ship`) at that moment.
#[cfg(feature = "vr")]
fn ride(&self, ship: Mat4, position: bevy::math::Vec3) -> Option<Vec<(usize, Mat4)>> {
    let mut r = self.pilot_ride.lock().ok()?;
    let start = *r.start.get_or_insert(position);
    if r.latch.is_none() {
        if start.distance(position) < 0.3 { return None; }
        let placed = self.poses.iter()
            .filter(|a| !(530..=533).contains(&a.class) && !a.hidden)
            .filter_map(|a| Some((a.actor, self.placement(a)?)))
            .collect();
        r.latch = Some((ship.inverse(), placed));
    }
    let (inverse, placed) = r.latch.as_ref()?;
    Some(placed.iter().filter_map(|&(k, then)| {
        let now = self.placement(self.poses.iter().find(|a| a.actor == k)?)?;
        Some((k, ship * *inverse * then * now.inverse()))
    }).collect())
}

