/// (crate::level_stream::drop_later).
pub fn remove<T: Resource>(mut commands: Commands) {
    commands.queue(|w: &mut World| {
        if let Some(old) = w.remove_resource::<T>() { crate::level_stream::drop_later(old); }
    });
