/// [`LevelUnload`]: `T` back to its default (a per-frame or per-level cache built at the plugin's `build`). The old
/// value is freed off the main thread.
pub fn reset<T: Resource<Mutability = Mutable> + Default>(mut commands: Commands) {
    commands.queue(|w: &mut World| replace_resource(w, T::default()));
}

/// Inserts `value`, the replaced one freed off the main thread (an existing resource is changed, as by
/// `insert_resource`).
fn replace_resource<T: Resource<Mutability = Mutable>>(world: &mut World, value: T) {
    match world.get_resource_mut::<T>() {
        Some(mut r) => crate::level_stream::drop_later(std::mem::replace(&mut *r, value)),
        None => world.insert_resource(value),
    }
}

