/// A [`crate::level_stream`] job despawning `left` a few hundred at a time.
fn despawn_job(mut left: Vec<Entity>) -> crate::level_stream::Job {
    Box::new(move |world: &mut World, deadline: std::time::Instant| {
        while !left.is_empty() {
            let from = left.len().saturating_sub(256);
            for e in left.drain(from..) {
                if world.get_entity(e).is_ok() { world.despawn(e); }
            }
            if std::time::Instant::now() >= deadline { break; }
        }
        left.is_empty()
    })
}

