/// VR: a turret axis aimed at an angle `error` away. The speed `v` (radians a tick) heads for it at most at `max`, no
/// faster than it can still brake from at `dec`, easing over the last ticks, approached at `acc` (speeding up) or `dec`;
/// it lands without overshooting.
pub fn aim_speed(v: &mut f32, error: f32, max: f32, acc: f32, dec: f32) {
    let want = error.signum() * max.min((2.0 * dec * error.abs()).sqrt()).min(error.abs() * 0.25);
    let rate = if want * *v > 0.0 && want.abs() > v.abs() { acc } else { dec };
    approach(want, rate, v);
    if error * *v >= 0.0 && v.abs() >= error.abs() {
        *v = error;
    }
}

