pub enum VrBody {
    /// Never (the default): the body is hidden, only the hands are drawn in play.
    Off,
    /// In scenes and ship sequences.
    Cutscenes,
    /// In scenes, ship sequences and play (the forearms collapsed too: the VR hands are the hands).
    Always,
}

impl VrBody {
    const KEYS: [&'static str; 3] = ["off", "cutscenes", "always"];
    pub fn index(self) -> u8 { self as u8 }
    pub fn from_index(v: u8) -> VrBody { [VrBody::Off, VrBody::Cutscenes, VrBody::Always][(v as usize).min(2)] }
    fn key(self) -> &'static str { Self::KEYS[self as usize] }
    #[cfg(feature = "vr")]
    fn parse(s: &str) -> VrBody { Self::KEYS.iter().position(|k| *k == s.trim()).map_or(VrBody::Off, |i| Self::from_index(i as u8)) }
}

