/// The ties of a level built off the main thread ([`prepare`]): the class meshes, the images, the instance records
/// and the part entities to spawn ([`spawn_prepared`]).
pub struct TiePrepared {
    meshes: Vec<Mesh>,
    /// The magenta fallback first, then one image per (texture, wrap) at its first use.
    images: Vec<Image>,
    /// Per material, at its first use: its image, MXL and GS draw.
    materials: Vec<(usize, u32, GsPass)>,
    /// One `TieInst` per gameplay instance ([`write_record`]).
    records: Vec<u8>,
    lod_inputs: Vec<crate::tie_lod::TieLodInput>,
    plan: Vec<PartEntity>,
    /// Per placed instance: its index and its range of `plan`.
    instances: Vec<(u32, std::ops::Range<usize>)>,
    tint: f32,
