/// The screen's last row a stretched panel may reach (the draw buffer is 416 high).
const STRETCH_BOTTOM: i32 = 404;

/// The model-space z offsets of the four corners (model units, `p`) that make a panel `grow` times its height taller:
/// the bottom corners (the lower z: the menu camera looks along +x, z up) down as far as the screen leaves room, the
/// top ones up for the rest. `ends` are corners 0 and 3 in the world, for the panel's screen rect.
fn stretch(proj: &MenuProjection, ends: [V4; 2], p: &[V4], grow: f32) -> [f32; 4] {
    let [_, y, _, h] = proj.screen_rect(ends[0], ends[1]);
    let z: Vec<f32> = p.iter().map(|c| f32::from_bits(c[2])).collect();
    let (top, bottom) = (z.iter().copied().fold(f32::MIN, f32::max), z.iter().copied().fold(f32::MAX, f32::min));
    if h <= 0 || top - bottom <= 0.0 { return [0.0; 4]; }
    let extra = h as f32 * grow;
    let down = extra.min((STRETCH_BOTTOM - (y + h)).max(0) as f32);
    let per_px = (top - bottom) / h as f32;
    let mid = (top + bottom) / 2.0;
    std::array::from_fn(|k| if z[k] < mid { -down * per_px } else { (extra - down) * per_px })
}

